import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});
 await new Promise(r=>setTimeout(r,500));
 const output='docs/diario-ia/qa-resultados/introducao-cinematografica';await mkdir(output,{recursive:true});
 await evaluate(`(async()=>{
  const {ToyRoomIntroduction}=await import('/src/js/cinematics/ToyRoomIntroduction.js');
  const {AssetManager}=await import('/src/js/assets/AssetManager.js');
  const assets=new AssetManager();await assets.loadManifest();await assets.preload();await document.fonts.load('600 25px Caveat');window.qaAssets=assets;
  for(const key of ['toy-room-intro-room-v1','toy-room-intro-girl-v1','toy-room-illustrated-fairy-v1'])if(!assets.get(key))throw Error('Arte ausente: '+key);
  document.body.innerHTML='<canvas id="qa"></canvas>';document.body.style.cssText='margin:0;background:#100c10';
  window.qaCanvas=document.querySelector('#qa');window.events=[];window.completed=0;
  window.intro=new ToyRoomIntroduction({onEvent:name=>events.push(name),onComplete:()=>completed++});
  intro.start({assets});
 })()`);
 for(const [width,height] of [[1280,720],[390,844],[844,390],[320,568]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:width<900});
  for(const [name,time] of [['chegada',2.6],['surpresa',5.3],['olhar-sala',9.3],['reflexao',14],['nanda',19.3]]){
   const result=await evaluate(`(()=>{const c=qaCanvas;c.width=${width};c.height=${height};c.style.width='${width}px';c.style.height='${height}px';intro.time=${time};intro.render(c.getContext('2d'),c);return {stage:intro.stage.id,camera:intro.cameraFrame(c),line:intro.dialogue};})()`);
   const f=result.camera,v=f.viewport;
   assert.ok(Number.isFinite(f.zoom)&&f.zoom>0,'Escala válida');
   // Menina e fada continuam visíveis nos planos de diálogo em todas as orientações.
   for(const [x,y] of [[710,400],[990,385]]){const px=width/2+(x-f.x)*f.zoom,py=v.y+v.height/2+(y-f.y)*f.zoom;assert.ok(px>=0&&px<=width&&py>=v.y&&py<=v.y+v.height,'Atuação dentro do plano');}
   const shot=await call('Page.captureScreenshot',{format:'png'});const bytes=Buffer.from(shot.result.data,'base64');
   await writeFile(output+'/'+width+'x'+height+'-'+name+'.png',bytes);await writeFile('/tmp/legendgirl-intro-'+width+'x'+height+'-'+name+'.png',bytes);
  }
 }
 await call('Emulation.setUserAgentOverride',{userAgent:'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 Chrome/130 Mobile Safari/537.36'});
 for(const [width,height] of [[390,844],[844,390],[320,568]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:true});
  const metrics=await evaluate(`(async()=>{const {renderPoeticNarration,POETIC_LINES}=await import('/src/js/narrative/PoeticNarrator.js');const {getMobileDialogueRegions}=await import('/src/js/ui/MobileDialogueRegion.js');const c=qaCanvas;c.width=${width};c.height=${height};c.style.width='${width}px';c.style.height='${height}px';const ctx=c.getContext('2d');ctx.fillStyle='#a98067';ctx.fillRect(0,0,c.width,c.height);intro.time=14;intro.render(ctx,c);const boxes=[];for(const text of Object.values(POETIC_LINES)){boxes.push(renderPoeticNarration(ctx,c,text,{separateScene:true,anchor:{top:c.height*.35,bottom:c.height*.65}}));}intro.render(ctx,c);const box=renderPoeticNarration(ctx,c,POETIC_LINES.toyRoomPlay);return {boxes,box,loaded:document.fonts.check('600 25px Caveat'),regions:getMobileDialogueRegions({left:0,top:0,right:c.width,bottom:c.height,marginX:16,marginY:16},box.height,'top')};})()`);
  assert.ok(metrics.loaded,'Fonte manuscrita local carregada');
  for(const b of metrics.boxes){assert.ok(b.y>=0&&b.y+b.height<height/2,'Narração no topo e sem corte');assert.ok(b.x-b.width/2>=0&&b.x+b.width/2<=width,'Moldura dentro da tela');}
  assert.ok(metrics.regions.panel.y+metrics.regions.panel.height<metrics.regions.scene.y,'Quadro superior separado da atuação');
  const shot=await call('Page.captureScreenshot',{format:'png'});const bytes=Buffer.from(shot.result.data,'base64');await writeFile(output+'/'+width+'x'+height+'-pastel.png',bytes);await writeFile('/tmp/legendgirl-intro-'+width+'x'+height+'-pastel.png',bytes);
 }
 const flow=await evaluate(`(()=>{intro.time=0;for(let i=0;i<1500;i++)intro.update(1);const result={events:[...events],completed,active:intro.active,released:intro.assets===null};intro.start({assets:{get(){return null}}});intro.cancel();result.cancelled=!intro.active&&intro.assets===null;return result;})()`);
 assert.deepEqual(flow.events,['PHASE1_COMPLETE','TOY_ROOM_START']);assert.equal(flow.completed,1);assert.equal(flow.active,false);assert.ok(flow.released&&flow.cancelled,'Conclusão e cancelamento liberam referências');
 console.log('APROVADO: 20 planos e narração pastel em desktop, retrato e paisagem; enquadramento dos atores, artes carregadas, eventos únicos, conclusão e cancelamento.',flow);

} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
